<?php require_once __DIR__.'/functions.php'; require_once __DIR__.'/app_init.php'; start_app('Mis mascotas','mascotas'); page_wrap_start('Mis mascotas','Consulta perfiles, información médica y carnet de vacunas.');
$pdo=dogvive_db(); $s=$pdo->prepare('SELECT * FROM mascota WHERE id_usuario=? ORDER BY id_mascota DESC'); $s->execute([dogvive_user_id()]); $pets=$s->fetchAll(); $ok=dogvive_flash('success'); $err=dogvive_flash('error');
if($ok) echo '<div class="notice">'.e($ok).'</div>'; if($err) echo '<div class="error-box">'.e($err).'</div>';
if(!$pets) echo '<div class="card"><h3>Aún no has registrado mascotas</h3><p class="muted">Crea el primer perfil para guardar sus datos y vacunas.</p>'.btn('＋ Registrar mascota',page_url('registro-mascota'),'btn-primary').'</div>';
else { echo '<div class="grid grid-2">'; foreach($pets as $pet) { $v=$pdo->prepare('SELECT COUNT(*) FROM vacuna WHERE id_mascota=?'); $v->execute([$pet['id_mascota']]); $count=(int)$v->fetchColumn(); $photo=$pet['Foto']?base_url().'/'.$pet['Foto']:''; echo '<article class="card pet-card">'; if($photo) echo '<img src="'.e($photo).'" alt="Foto de '.e($pet['Nombre']).'">'; else echo '<div class="avatar" style="width:90px;height:90px">🐾</div>'; echo '<div class="pet-card-body"><h3>'.e($pet['Nombre']).'</h3><p class="muted">'.e($pet['Especie'].' · '.$pet['Raza']).'</p><div class="tag-row"><span class="badge">'.e((string)$pet['Edad']).' años</span><span class="badge">'.e($pet['Sexo']??'').'</span><span class="badge green">'.$count.' vacunas</span></div><p class="muted">Carnet de vacunas y datos médicos en su perfil.</p>'.btn('Ver expediente y vacunas',base_url().'/mascota-perfil.php?id='.(int)$pet['id_mascota'],'btn-primary full').'</div></article>'; } echo '</div>'; echo '<div style="margin-top:18px">'.btn('＋ Agregar otra mascota',page_url('registro-mascota'),'btn-secondary').'</div>'; }
page_wrap_end(); end_app();
